const C={heaven:"Heaven & Resurrection",end:"Kingdom & End Times",hell:"Hell, Satan & Angels",assumptions:"Common Assumptions",tradition:"Tradition & Experience"};
const q=(question,category,answer,refs,takeaway,aliases="",sources=[])=>({question,category,answer,refs,takeaway,aliases,sources});
const questions=[
q("Where do believers go when they die?",C.heaven,"Believers who die are described as being with Christ. Scripture also looks ahead to Christ's return, the resurrection of the dead, judgment, and the new creation.",["Luke 23:43","Philippians 1:21-23","2 Corinthians 5:6-8","1 Thessalonians 4:13-17","1 Corinthians 15:51-54","Matthew 25:31-46","Revelation 21:1-5"],"With Christ after death is real, but it is not the end of the Christian story.","death tonight paradise afterlife go heaven"),
q("Is Heaven our final destination?",C.heaven,"Not exactly. Heaven is real, but the final biblical hope is resurrection and life with God in the new heavens and new earth.",["1 Corinthians 15:51-54","2 Peter 3:13","Revelation 21:1-3"],"Heaven is real. It just is not the last chapter.","final home eternity new earth destination"),
q("What is the intermediate state?",C.heaven,"“Intermediate state” is a theological term for the interval between death and bodily resurrection. Paul speaks of departing to be with Christ and being present with the Lord away from the body, while 1 Thessalonians looks to resurrection at Christ's coming. Christians differ on how these texts describe consciousness before resurrection.",["Philippians 1:23","2 Corinthians 5:8","1 Thessalonians 4:13-17"],"Being with Christ after death and bodily resurrection are related, but distinct, hopes.","between death resurrection waiting state"),
q("Do we become angels?",C.heaven,"No. Angels and humans are distinct creatures. Jesus says resurrected people are like angels in not marrying, not that they turn into angels.",["Matthew 22:30","Hebrews 1:13-14","1 Corinthians 6:3"],"Resurrection restores human life; it does not change humans into angels.","turn into angel wings loved ones"),
q("Do we become spirits forever?",C.heaven,"No. Christian hope is bodily resurrection. Our present bodies are transformed into imperishable, glorious bodies.",["Luke 24:39-43","1 Corinthians 15:42-53","Philippians 3:20-21"],"Christianity promises resurrection, not permanent ghostlike existence.","ghosts souls disembodied forever"),
q("What is a spiritual body?",C.heaven,"Paul calls the resurrection body a “spiritual body,” still a body, and contrasts corruption with incorruption, dishonour with glory, weakness with power, and mortality with immortality. It is made alive by God's Spirit.",["1 Corinthians 15:42-54","Romans 8:11","Philippians 3:21"],"Spiritual body means Spirit-empowered body, not no body.","ghost physical spiritual body"),
q("What will our resurrected bodies be like?",C.heaven,"They will be imperishable, glorious, powerful, and conformed to Christ's risen body. Scripture gives the promise more clearly than every physical detail.",["1 Corinthians 15:42-54","Philippians 3:20-21","1 John 3:2"],"God transforms embodied human life rather than discarding it.","new body look like age disabilities perfect"),
q("Did Jesus rise physically?",C.heaven,"Yes. The resurrection accounts report an empty tomb and appearances in which Jesus showed His wounds, invited touch, and ate with His disciples. They present a bodily resurrection, with the risen body also transformed in glory.",["Luke 24:1-12","Luke 24:36-43","John 20:1-10","John 20:24-29","1 Corinthians 15:42-49","Philippians 3:20-21"],"Jesus' physical resurrection is the pattern and foundation of ours.","ghost empty tomb flesh bones body"),
q("Will we recognize each other?",C.heaven,"Scripture shows personal identity continuing—Moses and Elijah are identified at the Transfiguration, and the risen Jesus is recognized in His appearances—but it does not explicitly promise that believers will recognize one another or explain memory and relationships after resurrection.",["Matthew 17:1-4","Luke 24:36-43","John 20:16-20","John 21:9-14"],"Continuing identity is biblical; the details of future recognition are inferred rather than directly explained.","know family loved ones remember identity"),
q("Will there be marriage?",C.heaven,"Jesus says those who attain the resurrection neither marry nor are given in marriage. Revelation's “marriage of the Lamb” is imagery for Christ and His people, not a statement that earthly spousal marriages continue; Scripture does not detail other relationships.",["Matthew 22:23-30","Luke 20:34-36","Revelation 19:7-9"],"Resurrection life is not simply today's social order extended forever.","spouse husband wife married heaven"),
q("Will there be procreation?",C.heaven,"The cited passages do not say whether resurrected people will have children. Jesus says resurrection life involves no marriage and no death, so Scripture gives no basis for asserting ongoing procreation; the question should be left open rather than answered with a definitive no.",["Matthew 22:30","Luke 20:34-36","Revelation 21:4"],"Scripture does not answer this directly, so certainty would go beyond the text.","babies children sex reproduce heaven"),
q("Will we eat?",C.heaven,"The risen Jesus ate, and Scripture uses feast and Tree of Life imagery for God's completed kingdom. Exactly how food functions in resurrection life is not fully explained.",["Luke 24:41-43","Isaiah 25:6-9","Revelation 22:1-2"],"Resurrection is embodied life, not an escape from everything physical.","food drink feast meals heaven"),
q("Will we work?",C.heaven,"God gave humanity work before the fall. Genesis later describes painful toil as a consequence of the curse, while Revelation portrays God's servants serving and reigning where there is no more curse.",["Genesis 2:15","Genesis 3:17-19","Revelation 22:3-5","Colossians 3:17"],"Work is not the curse; corrupted and painful toil is.","jobs labor bored occupation serve"),
q("Will we worship constantly?",C.heaven,"Scripture portrays God's servants serving Him and reigning forever, and it calls believers to offer their whole lives to God. It does not specify a continuous schedule of singing or services, and it does not explicitly mention creating in the final state.",["Romans 12:1","Revelation 22:3-5","Colossians 3:17"],"Eternal worship is certain; its daily form is not fully described.","sing forever church service boring"),
q("Will we live with God?",C.heaven,"Yes. Scripture's closing picture is God dwelling with humanity, His throne among His people, and His servants seeing His face.",["Revelation 21:3-4","Revelation 22:3-5","John 14:1-3"],"The final hope is not merely visiting Heaven; it is life with God forever.","see God face presence new jerusalem"),
q("What happens to creation?",C.heaven,"Romans 8 says creation is subject to corruption but awaits liberation; Revelation says, “I make all things new.” These texts support redemption of creation while not specifying exactly how the present world relates to the new.",["Genesis 1:31","Romans 8:19-23","Revelation 21:1-5"],"Redemption includes creation as well as people, though its exact continuity is debated.","earth destroyed animals nature renewal"),
q("What does “new heaven and new earth” mean?",C.heaven,"It describes a new heavens and new earth in which righteousness dwells. Revelation says God lives with His people, death and pain are gone, and there is no more curse; the passages do not settle every question about continuity with the present creation.",["Isaiah 65:17","2 Peter 3:13","Revelation 21:1-5","Revelation 22:3-5"],"The Bible ends with new creation and God's presence; the exact nature of continuity is debated.","new heavens earth replacement renewal eternity"),
q("What happened to Lazarus while he was dead?",C.heaven,"The Bible does not tell us what Lazarus experienced. John focuses on Jesus as the resurrection and the life, not on an afterlife report from Lazarus.",["John 11:11-15","John 11:23-26","John 11:38-44"],"When Scripture is silent, we should resist inventing certainty.","four days tomb heaven testimony bethany"),
q("Do near-death experiences prove someone visited Heaven?",C.heaven,"No. A near-death experience is not, by itself, biblical proof that someone visited Heaven. Scripture commands believers to test spiritual claims and hold fast to what is good; an experience cannot establish doctrine or override the apostolic gospel.",["1 John 4:1","Galatians 1:8","1 Thessalonians 5:21","Acts 17:11"],"Experience may be meaningful, but Scripture evaluates experience.","nde died saw Jesus granny light trip visions"),
q("What is the Kingdom of God?",C.end,"The Kingdom is God's reign announced and inaugurated through Jesus: it is “at hand,” and His works show it has come, while believers still pray for its full arrival. Scripture also looks to Christ's final victory over every opposing power.",["Matthew 4:17","Matthew 6:9-10","Matthew 12:28","Revelation 11:15","1 Corinthians 15:24-26"],"The Kingdom is God's rule, not merely another name for Heaven.","kingdom heaven reign rule Jesus"),
q("What is the Rapture?",C.end,"“Rapture” is a later label for the catching-up described in 1 Thessalonians. There Christ descends, the dead in Christ rise, and living believers are caught up to meet Him; whether Matthew 24 describes the same event is interpreted differently.",["1 Thessalonians 4:13-18","1 Corinthians 15:51-52","Matthew 24:29-31"],"The catching up is biblical; detailed timelines built around it are interpretations.","caught up disappear left behind"),
q("Is a pre-tribulation Rapture explicitly stated?",C.end,"No passage presents the popular seven-year pre-tribulation sequence as a complete outline. Matthew 24:29-31 places the gathering “after the tribulation,” while 2 Thessalonians 2:1-4 links Christ's coming and our gathering with events preceding “that day”; Christians interpret these relationships differently.",["Matthew 24:29-31","1 Thessalonians 4:16-17","2 Thessalonians 2:1-4"],"Separate the event Scripture states from the timeline an interpretive system constructs.","pretrib seven years secret rapture tribulation timeline"),
q("What happens when Christ returns?",C.end,"At Christ's public coming, He appears in glory and gathers His people; the dead in Christ rise, living believers are changed, and Scripture elsewhere portrays judgment and the defeat of every opposing power. These passages establish the events but not a complete end-times sequence.",["Matthew 24:29-31","1 Thessalonians 4:16-17","1 Corinthians 15:23-26","1 Corinthians 15:51-52","Matthew 25:31-46"],"Christ's return is public, victorious, and bound to resurrection.","second coming Jesus comes back"),
q("What is the last trumpet?",C.end,"Paul says the “last trump” accompanies the resurrection of the dead and the change of living believers; 1 Thessalonians also associates a trumpet with Christ's descent. Revelation's seventh trumpet announces God's reign and judgment, but the passages do not explicitly identify it with Paul's “last trumpet.”",["1 Corinthians 15:51-52","1 Thessalonians 4:16","Revelation 11:15-18"],"Scripture ties Paul's trumpet to resurrection; identifying it with Revelation's seventh trumpet is an interpretation.","trump sound trumpet end times"),
q("What is the first resurrection?",C.end,"Revelation 20 calls those who live and reign with Christ for a thousand years participants in the “first resurrection” and calls them blessed. John 5 and 1 Corinthians describe resurrection more broadly but do not explicitly equate their sequence with Revelation 20; interpretations differ.",["Revelation 20:4-6","John 5:28-29","1 Corinthians 15:22-23"],"Affirm what the text says while acknowledging where faithful interpretations differ.","raised first millennium martyrs"),
q("What is the 1,000-year reign?",C.end,"Revelation 20 describes a thousand-year period in which the dragon is bound and those who share in the first resurrection reign with Christ. Isaiah 11 and 1 Corinthians 15 are passages some interpreters relate to this hope, but neither mentions a thousand years; Christians disagree over whether the millennium is future and literal, symbolic, or otherwise.",["Revelation 20:1-10","Isaiah 11:1-9","1 Corinthians 15:24-26"],"The reign of Christ is certain; its detailed chronology is debated.","millennium thousand years premillennial amillennial"),
q("Do believers reign with Christ?",C.end,"Scripture promises that Christ's people—those who belong to Him and endure—will reign with Him. Paul makes the promise conditional on enduring, and Revelation describes God's servants reigning forever. The passages do not define the scope or duties of that reign.",["2 Timothy 2:12","Revelation 5:9-10","Revelation 22:3-5"],"Eternal life includes meaningful service under Christ's rule.","rule nations kings authority"),
q("What happens after the Millennium?",C.end,"Within Revelation 20-21's narrated sequence, after the thousand years Satan is released, defeated, and judged; the dead stand before the great white throne, and Revelation then shows a new heaven and new earth. How this maps onto the whole biblical end-times timeline is debated.",["Revelation 20:7-15","Revelation 21:1-5"],"Evil's final uprising ends in permanent defeat before new creation.","after thousand years Satan released Gog Magog"),
q("What is the final judgment?",C.end,"Scripture portrays a final judgment in which God judges with righteous impartiality: Revelation says the dead are judged according to their works, and the Book of Life marks those spared the lake of fire. The wider New Testament teaches that salvation is God's grace in Christ, not a wage earned by works.",["Matthew 25:31-46","Revelation 20:11-15","Romans 2:5-11","Ephesians 2:8-10"],"Final judgment belongs to the perfectly just God, not to human guesswork.","great white throne books judgment day"),
q("When is death finally destroyed?",C.end,"Paul calls death the last enemy to be destroyed. Revelation places death and Hades in the lake of fire and then depicts the new creation in which death is no more.",["1 Corinthians 15:24-26","Revelation 20:14","Revelation 21:1-4"],"Christian hope is not merely surviving death; it is death's complete defeat.","last enemy no more death"),
q("Does Satan rule Hell?",C.hell,"No. Scripture presents the lake of fire as Satan's punishment, not his kingdom or throne. God judges Satan.",["Matthew 25:41","Revelation 20:10","Revelation 20:14-15"],"Satan is not Hell's king; he is among those judged.","devil king ruler demons pitchfork"),
q("Is Satan currently in Hell?",C.hell,"Scripture depicts Satan prowling the earth; Job portrays him appearing before the LORD, while Revelation 12 portrays the ancient serpent cast down to earth. Revelation 20 places his final confinement in the lake of fire after the thousand years in its narrative sequence. These passages do not provide a simple present-day map of his location.",["Job 1:6-7","1 Peter 5:8","Revelation 12:9-12","Revelation 20:10"],"The Bible does not picture Satan presently governing from Hell.","devil lives hell now roaming earth"),
q("Are Hades and the lake of fire the same?",C.hell,"No. Revelation says death and Hades are themselves thrown into the lake of fire, showing that the terms are not identical.",["Revelation 1:18","Revelation 20:13-15","Luke 16:23"],"Related judgment terms should not be flattened into one interchangeable word.","hell hades fire final punishment"),
q("What are Sheol, Hades, and Gehenna?",C.hell,"English Bibles translate several terms as “hell.” In the underlying terminology, Sheol and Hades refer in these contexts to the realm of the dead, while Gehenna is used in Jesus' warnings about judgment and unquenchable fire. The terms overlap in English but are not automatically interchangeable; these verses do not give a complete map of intermediate and final states.",["Psalm 16:10","Acts 2:27","Matthew 10:28","Mark 9:43-48","Revelation 20:13-15"],"Read each biblical term in context instead of assuming every English “Hell” means exactly the same thing.","grave underworld gehenna hell words"),
q("Is Lucifer actually Satan's name?",C.hell,"In Isaiah 14 the immediate oracle is a taunt against Babylon's king. The KJV uses “Lucifer” in verse 12; other translations render the image as “morning star.” Later Christian tradition applied the passage to Satan, while some readers see a secondary or typological allusion. Isaiah itself does not explicitly name Satan.",["Isaiah 14:4","Isaiah 14:12-15"],"A traditional label is not always what the passage explicitly names.","devil name morning star king Babylon"),
q("Was the Genesis serpent Satan?",C.hell,"Genesis calls the tempter the serpent. Later Scripture identifies “that ancient serpent” with the Devil and Satan, making the connection biblical even though Genesis does not use Satan's name.",["Genesis 3:1-15","Revelation 12:9","Revelation 20:2"],"Later Scripture identifies the ancient serpent while Genesis itself emphasizes the serpent's deception.","snake garden Eden devil"),
q("Do angels have wings?",C.hell,"Isaiah describes seraphim with six wings, and Ezekiel describes cherubim with four. Hebrews says some people have entertained angels without knowing it, but these passages do not establish what every angel looks like.",["Isaiah 6:1-3","Ezekiel 10:19-21","Hebrews 13:2"],"The Bible does not say every angel looks like a winged human.","feathers cherub seraph messenger"),
q("Do dead humans become angels?",C.hell,"No. Humans and angels remain distinct. Jesus says resurrected people are like angels in certain respects, especially not dying or marrying.",["Luke 20:34-36","Hebrews 1:13-14","1 Corinthians 6:3"],"“Like angels” does not mean “become angels.”","loved one angel wings death"),
q("Does everyone have a guardian angel?",C.hell,"Scripture teaches that angels serve God's people and records angelic protection, but it does not plainly state that every individual has one permanently assigned personal angel.",["Psalm 91:11","Matthew 18:10","Hebrews 1:14"],"Angelic care is biblical; a one-person, one-guardian system is not explicitly defined.","personal angel assigned protection"),
q("Are believers already called saints?",C.assumptions,"Yes. In these New Testament letters, “saints” addresses living believers set apart in Christ. Some later churches also use “saint” as an honorific for canonized Christians; that later usage is distinct from this ordinary New Testament address.",["Romans 1:7","1 Corinthians 1:2","Ephesians 1:1"],"In the New Testament letters, “saint” is an ordinary description of believers.","holy people canonized saint alive"),
q("Do good people go to Heaven?",C.assumptions,"No one earns reconciliation with God by being better than others: all have sinned, and salvation is God's gift through Christ. Ephesians also says those saved by grace are created for good works, so works are the fruit of salvation, not its purchase.",["Romans 3:23-24","Ephesians 2:8-10","John 14:6"],"The gospel is grace in Christ, with good works as its fruit rather than its price.","good person works earn salvation"),
q("Is work part of the curse?",C.assumptions,"No. God gave humanity work before sin. The curse brought painful toil, frustration, and hardship into work.",["Genesis 2:15","Genesis 3:17-19","Colossians 3:23"],"Work is part of human vocation; painful toil is part of the curse.","job labor garden Eden curse"),
q("Does “judge not” forbid judgment?",C.assumptions,"Jesus' command addresses hypocritical, condemning judgment: examine yourself first, then help your brother. Elsewhere He commands righteous judgment, and Paul discusses judgment and discipline within the church while leaving outsiders to God. These passages support humble discernment, not self-righteous condemnation.",["Matthew 7:1-5","John 7:24","1 Corinthians 5:12-13"],"Jesus forbids hypocritical condemnation, not humble moral discernment.","don't judge judging discernment hypocrisy"),
q("Does God promise not to give us more than we can handle?",C.assumptions,"No. First Corinthians 10:13 promises a way to endure temptation, not that every burden will stay within our personal strength. Paul describes affliction beyond his ability so he would rely on God.",["1 Corinthians 10:13","2 Corinthians 1:8-9","Psalm 55:22"],"God promises faithfulness in trial, not a life limited to what we can manage alone.","too much handle burden suffering temptation"),
q("What does “two or three gathered” actually mean?",C.assumptions,"In context, Jesus is teaching church discipline, agreement, and His authority among believers addressing sin. It is not primarily a formula for making a small gathering count as church.",["Matthew 18:15-20","Deuteronomy 19:15"],"Read the comforting phrase inside its difficult context of correction and reconciliation.","church attendance small group prayer meeting"),
q("Is money the root of all evil?",C.assumptions,"No. Paul says the love of money is a root of all kinds of evil. Money itself is a tool; greed and misplaced desire are the danger.",["1 Timothy 6:6-10","Hebrews 13:5","Matthew 6:24"],"The warning concerns love of money, not the mere existence of money.","wealth rich greed root evil"),
q("Were there three wise men?",C.assumptions,"Matthew names three kinds of gifts but never states the number of Magi. The familiar number three is an inference from the gifts.",["Matthew 2:1-12"],"Three gifts do not prove there were three visitors.","magi kings nativity gold frankincense myrrh"),
q("Was the forbidden fruit an apple?",C.assumptions,"Genesis calls it the fruit of the tree of the knowledge of good and evil but never identifies it as an apple.",["Genesis 2:16-17","Genesis 3:1-6"],"The apple belongs to later art and tradition, not the wording of Genesis.","Adam Eve garden fruit"),
q("Was Mary Magdalene a prostitute?",C.assumptions,"The Bible does not identify Mary Magdalene as a prostitute. Luke names her as a woman from whom seven demons had gone out and who supported Jesus' ministry; John identifies her as a resurrection witness. The later identification of her with Luke 7's unnamed “sinful woman” is a tradition or inference, not something the text states.",["Luke 7:36-50","Luke 8:1-3","John 20:1-18"],"Do not attach another person's unnamed story to Mary Magdalene.","sinful woman prostitute seven demons"),
q("Does “ask in My name” guarantee the answer?",C.assumptions,"Jesus promises to answer requests made in His name, but John 15 places that promise within abiding in Him and His words, and 1 John explicitly qualifies prayer as according to God's will. “In My name” is not a magic phrase or a guarantee that every request, isolated from Christ's will, will be granted.",["John 14:13-14","John 15:7","1 John 5:14-15"],"Prayer in Jesus' name belongs within abiding in Jesus and seeking God's will.","prayer anything want guaranteed request"),
q("Does the Bible say “God helps those who help themselves”?",C.assumptions,"No. That saying is not in Scripture. The Bible commends diligent action while repeatedly showing God helping people who cannot save themselves.",["Psalm 121:1-2","Romans 5:6-8","James 2:17"],"Biblical diligence never replaces dependence on God's grace.","quote proverb self help Benjamin Franklin"),
q("Is the soul naturally immortal?",C.tradition,"Scripture calls God immortal and describes believers putting on immortality in the resurrection. It does not clearly state that every human soul is inherently indestructible; Christians differ about what Scripture teaches concerning conscious existence between death and resurrection.",["1 Timothy 6:15-16","1 Corinthians 15:53-54","2 Timothy 1:10"],"These passages ground immortality in God and resurrection without settling every intermediate-state question.","immortal soul never dies Plato"),
q("Does the Bible teach that the body is a prison?",C.tradition,"Not as a general biblical teaching. Scripture calls creation very good and says God formed the human from dust. The present body is subject to corruption and awaits redemption, but Paul places Christian hope in bodily resurrection, not permanent escape from matter.",["Genesis 1:31","Genesis 2:7","Romans 8:23","1 Corinthians 15:42-49"],"Embodiment is part of the person God redeems, even though present mortal life is burdened by sin and decay.","soul trapped flesh cage Plato"),
q("Is physical creation inferior to spiritual existence?",C.tradition,"Scripture calls physical creation good. Both physical and spiritual creatures are created; God alone is uncreated. The problem addressed in Romans is corruption and sin, not physical existence itself.",["Genesis 1:31","Psalm 24:1","Romans 8:19-23"],"Biblical hope restores creation rather than treating matter as a mistake.","matter evil physical bad spiritual higher"),
q("Is death liberation or an enemy?",C.tradition,"Scripture calls death an enemy to be destroyed, and the gospel's final hope is resurrection, not permanent disembodiment. Scripture also portrays death as gain for the believer and speaks of being with Christ after death, so both truths should be held together.",["John 11:25-26","1 Corinthians 15:17-26","Philippians 1:21-23","2 Corinthians 5:6-8","Revelation 21:4"],"Believers may be with Christ after death, while resurrection remains the final victory over death.","release freedom soul body enemy"),
q("Did Greek philosophy influence Christian ideas about Heaven?",C.tradition,"In some cases, yes—but not as a simple origin story. Christianity developed in a Jewish and Hellenistic world; Platonist and later Neoplatonist categories shaped some Christian theologians and explanations of the afterlife. The extent varies by author and doctrine, and this does not mean Christian resurrection or Heaven was simply borrowed from Plato.",["Acts 17:11","Colossians 2:8","1 Thessalonians 5:21"],"Historical influence is complex; Scripture and historical sources must each be used for the claims they can actually establish.","Plato Greek Augustine soul body history",[{label:"Augustine, Confessions, Book VII",url:"https://www.newadvent.org/fathers/110107.htm"},{label:"Stanford Encyclopedia: Neoplatonism",url:"https://plato.stanford.edu/entries/neoplatonism/"}]),
q("What did Plato actually teach about the soul and body?",C.tradition,"In Plato's Phaedo, Socrates describes death as separation of soul and body, portrays bodily concerns as obstacles to philosophical knowledge, and argues for the soul's survival or immortality. Plato's wider writings are more varied. This differs in emphasis from the New Testament's central hope of bodily resurrection, although the New Testament also speaks of being with Christ before resurrection.",["Genesis 2:7","Philippians 1:21-23","1 Corinthians 15:12-23","1 Corinthians 15:42-54"],"Plato's Phaedo and the New Testament's resurrection teaching should not be treated as identical.","Phaedo immortal soul prison Greek",[{label:"Plato, Phaedo",url:"https://www.gutenberg.org/files/1658/1658-h/1658-h.htm"},{label:"Stanford Encyclopedia: Ancient Theories of Soul",url:"https://plato.stanford.edu/entries/ancient-soul/"}]),
q("What did Augustine actually teach about resurrection?",C.tradition,"Augustine engaged deeply with Platonism and held that the soul is incorporeal and immortal. He nevertheless defended the goodness of embodied human life and insisted that salvation culminates in resurrection of the body. His position combines philosophical influence with a central Christian doctrine rather than reducing the body to a disposable prison.",["Luke 24:39-43","1 Corinthians 15:42-54","Philippians 3:20-21"],"A thinker can carry philosophical influence while still defending bodily resurrection.","City of God Plato church father body",[{label:"Augustine, Confessions, Book VII",url:"https://www.newadvent.org/fathers/110107.htm"},{label:"Augustine, City of God, Book XXII",url:"https://www.newadvent.org/fathers/120122.htm"},{label:"Stanford Encyclopedia: Augustine",url:"https://plato.stanford.edu/entries/augustine/"}]),
q("Can Christian tradition be wrong?",C.tradition,"A particular tradition or interpretation can be mistaken. Jesus rebuked traditions that nullified God's word, and the Bereans were commended for testing teaching against Scripture. Christians differ about how Scripture and church tradition share authority.",["Mark 7:6-13","Acts 17:11","2 Timothy 3:16-17"],"Inherited teaching should be examined carefully, with humility about Christian differences over authority.","church teaching denomination inherited belief"),
q("Can a sincere spiritual experience still be mistaken?",C.tradition,"Yes. A sincere report may still be mistaken about what happened or what it means. Scripture tells believers to test spiritual claims rather than treating sincerity or intensity as proof.",["1 John 4:1","Galatians 1:8","1 Thessalonians 5:21"],"Scripture evaluates experience; sincerity alone does not establish the interpretation.","vision dream prophecy angel supernatural sincere"),
];

const els={search:document.querySelector("#questionSearch"),clear:document.querySelector("#clearSearch"),filters:document.querySelector("#categoryFilters"),summary:document.querySelector("#resultSummary"),results:document.querySelector("#questionResults"),top:document.querySelector("#backToTop")};
let activeCategory="All";
const stop=new Set(["a","an","and","are","can","do","does","did","for","from","in","is","it","of","on","or","our","the","to","we","what","when","where","will","with"]);
const normalize=value=>value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9\s]/g," ").replace(/\s+/g," ").trim();
const stem=word=>word.length>5?word.replace(/(ing|ers|ies|ied|ed|es|s)$/i,""):word;
const tokens=value=>normalize(value).split(" ").filter(word=>word&&!stop.has(word)).map(stem);
const bookSlugs={Genesis:"genesis",Psalm:"psalms",Psalms:"psalms",Isaiah:"isaiah",Ezekiel:"ezekiel",Matthew:"matthew",Mark:"mark",Luke:"luke",John:"john",Acts:"acts",Romans:"romans","1 Corinthians":"1-corinthians","2 Corinthians":"2-corinthians",Galatians:"galatians",Ephesians:"ephesians",Philippians:"philippians",Colossians:"colossians","1 Thessalonians":"1-thessalonians","2 Thessalonians":"2-thessalonians","1 Timothy":"1-timothy","2 Timothy":"2-timothy",Hebrews:"hebrews",James:"james","1 Peter":"1-peter","2 Peter":"2-peter","1 John":"1-john",Revelation:"revelation",Job:"job",Deuteronomy:"deuteronomy"};
function scriptureHref(ref){const match=ref.match(/^((?:[1-3] )?[A-Za-z]+) (\d+):(\d+)/);if(!match)return"/bible/";const slug=bookSlugs[match[1]];return slug?`/bible/#kjv.${slug}.${match[2]}.${match[3]}`:"/bible/"}
function score(item,query){if(!query)return 0;const phrase=normalize(query);const title=normalize(item.question);const alias=normalize(item.aliases);const hay=normalize(`${item.question} ${item.category} ${item.answer} ${item.takeaway} ${item.aliases} ${item.refs.join(" ")}`);let total=title===phrase?1000:title.includes(phrase)?300:alias.includes(phrase)?220:0;const queryTokens=tokens(query);const titleTokens=new Set(tokens(item.question));const aliasTokens=new Set(tokens(item.aliases));const hayTokens=new Set(tokens(hay));for(const word of queryTokens){if(titleTokens.has(word))total+=45;else if(aliasTokens.has(word))total+=34;else if(hayTokens.has(word))total+=12;else if([...hayTokens].some(candidate=>candidate.startsWith(word)||word.startsWith(candidate)))total+=5}return total/Math.max(1,queryTokens.length)}
function renderFilters(){els.filters.replaceChildren();["All",...new Set(questions.map(item=>item.category))].forEach(category=>{const button=document.createElement("button");button.type="button";button.className=`filter-button${category===activeCategory?" active":""}`;button.textContent=category;button.setAttribute("aria-pressed",String(category===activeCategory));button.addEventListener("click",()=>{activeCategory=category;renderFilters();render()});els.filters.append(button)})}
function card(item,index,best){const article=document.createElement("article");article.className=`question-card${best?" best-match":""}`;article.id=`question-${index+1}`;if(best){const label=document.createElement("p");label.className="match-label";label.textContent="Most likely match";article.append(label)}const button=document.createElement("button");button.type="button";button.className="question-button";button.setAttribute("aria-expanded",String(best));button.innerHTML=`<span class="question-number">${index+1}</span><span><strong class="question-heading">${item.question}</strong><span class="question-category">${item.category}</span></span><span class="expand-icon" aria-hidden="true">${best?"−":"+"}</span>`;const detail=document.createElement("div");detail.className="question-detail";detail.hidden=!best;const answer=document.createElement("p");answer.className="answer";answer.textContent=item.answer;const readLabel=document.createElement("p");readLabel.className="read-label";readLabel.textContent="Read in the Digital Bible";const refs=document.createElement("div");refs.className="references";item.refs.forEach(ref=>{const link=document.createElement("a");link.className="reference-link";link.href=scriptureHref(ref);link.textContent=ref;refs.append(link)});detail.append(answer,readLabel,refs);if(item.sources.length){const sourceLabel=document.createElement("p");sourceLabel.className="read-label source-label";sourceLabel.textContent="Historical sources";const sources=document.createElement("div");sources.className="references sources";item.sources.forEach(source=>{const link=document.createElement("a");link.className="source-link";link.href=source.url;link.textContent=source.label;link.target="_blank";link.rel="noopener noreferrer";sources.append(link)});detail.append(sourceLabel,sources)}const takeaway=document.createElement("p");takeaway.className="takeaway";const strong=document.createElement("strong");strong.textContent="Takeaway: ";takeaway.append(strong,item.takeaway);detail.append(takeaway);button.addEventListener("click",()=>{detail.hidden=!detail.hidden;button.setAttribute("aria-expanded",String(!detail.hidden));button.querySelector(".expand-icon").textContent=detail.hidden?"+":"−"});article.append(button,detail);return article}
function render(){const query=els.search.value.trim();const ranked=questions.map((item,index)=>({item,index,score:score(item,query)})).filter(row=>activeCategory==="All"||row.item.category===activeCategory).sort((a,b)=>query?b.score-a.score:a.index-b.index);const visible=query?ranked.filter(row=>row.score>0):ranked;els.results.replaceChildren();if(!visible.length){const empty=document.createElement("div");empty.className="empty-state";empty.innerHTML="<h2>No close match found</h2><p>Try a shorter phrase such as <em>resurrection</em>, <em>angels</em>, <em>Rapture</em>, or <em>tradition</em>.</p>";els.results.append(empty)}else visible.forEach((row,position)=>els.results.append(card(row.item,row.index,Boolean(query)&&position===0)));els.clear.hidden=!query;els.summary.textContent=query?(visible.length?`${visible.length} likely ${visible.length===1?"match":"matches"}. The closest question is first.`:"No likely matches found."):`Showing ${visible.length} of 60 questions${activeCategory==="All"?"":` in ${activeCategory}`}.`}
let searchTimer;els.search.addEventListener("input",()=>{clearTimeout(searchTimer);searchTimer=setTimeout(render,90)});els.search.addEventListener("keydown",event=>{if(event.key==="Enter"){event.preventDefault();render();document.querySelector(".question-card")?.scrollIntoView({behavior:"smooth",block:"start"})}});els.clear.addEventListener("click",()=>{els.search.value="";els.search.focus();render()});window.addEventListener("scroll",()=>{els.top.hidden=window.scrollY<700},{passive:true});els.top.addEventListener("click",()=>window.scrollTo({top:0,behavior:"smooth"}));renderFilters();render();
els.results.addEventListener("click",event=>{const link=event.target.closest?.(".reference-link");if(!link)return;const article=link.closest(".question-card");const questionNumber=Number(article?.id.replace("question-",""));const target=new URL(link.href,location.href);target.searchParams.set("returnTo","questions");if(questionNumber)target.searchParams.set("question",String(questionNumber));const guideQuery=els.search.value.trim();if(guideQuery)target.searchParams.set("guideQuery",guideQuery);link.href=`${target.pathname}${target.search}${target.hash}`});
const guideParams=new URLSearchParams(location.search);const returnedQuestion=Number(guideParams.get("question"));const returnedQuery=guideParams.get("q")?.trim()||"";if(returnedQuery){els.search.value=returnedQuery;render()}if(Number.isInteger(returnedQuestion)&&returnedQuestion>=1&&returnedQuestion<=60){requestAnimationFrame(()=>{const article=document.querySelector(`#question-${returnedQuestion}`);if(!article)return;const detail=article.querySelector(".question-detail");const button=article.querySelector(".question-button");if(detail?.hidden)button?.click();article.scrollIntoView({behavior:"smooth",block:"start"})})}
